    "An agent's positive value attribution to an identified agent in a stated context."
    links imod:Agent to imod:Agent;

proposals.integrated_declaration:
functional directed relationship ValuesAgent
    "An agent's positive value attribution to an identified agent in a stated context."
    links imod:Agent to imod:Agent;

proposals.original_declaration:
process ValueAttribution
    "Activity through which an agent attributes value to an identified entity or alternative."
    is physical:Activity of imod:Agent;

proposals.integrated_declaration:
process ValueAttribution
    "Activity through which an agent attributes value to an identified entity or alternative."
    is physical:Activity of imod:Agent;

proposals.original_declaration:
abstract priority NonmonetaryImportance
    "An ordinal assessment of the importance of an identified substantial under explicit evaluative criteria."
    is imod:Priority of (imod:Subject or imod:Agent);

process ValueDeliberation
    "Activity in which participants examine and discuss value judgments about identified alternatives."
    is physical:Activity of imod:Agent;

proposals.integrated_declaration:
process ValueDeliberation
    "Activity in which participants examine and discuss value judgments about identified alternatives."
    is physical:Activity of imod:Agent;

proposals.original_declaration:
process MonetaryAppraisal
    "Activity through which an agent estimates a monetary amount for a specified valuation concept and target."
    is physical:Activity of imod:Agent;

proposals.integrated_declaration:
process MonetaryAppraisal
    "Activity through which an agent estimates a monetary amount for a specified valuation concept and target."
    is physical:Activity of imod:Agent;

proposals.original_declaration:
attribute RegardedAsNonSubstitutable
    "Characterized by an explicit judgment that no substitute is acceptable within the stated evaluative context."
    applies to (imod:Subject or imod:Agent);

event ValuationStatement
    "A bounded occurrence in which an agent expresses an identified value judgment."
    ;

